def is_valid_ipv4(s: str) -> bool:
    if not s or len(s) > 15:
        return False

    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        # Check for empty string, whitespace, signs, or non-digit characters
        if not part or part[0] == '-' or part[0] == '+':
            return False

        # Check for leading zeros (unless the number is just "0")
        if len(part) > 1 and part[0] == '0':
            return False

        # Check if all characters are digits
        if not part.isdigit():
            return False

        num = int(part)
        if num < 0 or num > 255:
            return False

    return True
